-- ============================================================
-- Fantasy Bake Off — seed
-- ============================================================
-- Run last. Safe to re-run: every insert is idempotent.
--
-- What this does NOT seed: bakers (the cast isn't announced) and players
-- (generated by scripts/generate-players.mjs into players.seed.sql, which is
-- git-ignored because a code is a credential).

-- ------------------------------------------------------------
-- Categories — the points table from RULES §2.1 and §4
-- ------------------------------------------------------------
-- Editable at any time. Because scoring is views, an UPDATE here is retroactive
-- across every league the instant it lands.

insert into categories (key, label, points, sort_order, applies_to) values
  ('best',      'Best Baker',       4, 1, 'regular'),
  ('leaving',   'Leaving Baker',    3, 2, 'regular'),
  ('technical', 'Technical Winner', 2, 3, 'both'),
  ('bingo',     'Bingo Bonus',      2, 4, 'both'),
  ('handshake', 'Handshake',        2, 5, 'both'),
  ('winner',    'Winner of Bake Off', 5, 0, 'final')
on conflict (key) do update
  set label      = excluded.label,
      points     = excluded.points,
      sort_order = excluded.sort_order,
      applies_to = excluded.applies_to;

-- ------------------------------------------------------------
-- The season
-- ------------------------------------------------------------

insert into seasons (name, year, episode_count, is_active)
select 'GBBO 2026', 2026, 10, true
where not exists (select 1 from seasons where name = 'GBBO 2026');

-- ------------------------------------------------------------
-- The league
-- ------------------------------------------------------------
-- One to start. `is_default` is what an anonymous visitor to "/" lands on;
-- a partial unique index allows only one per season.
--
-- Change the name and slug to whatever you're calling it — the slug is the
-- public URL, /league/<slug>.

insert into leagues (season_id, name, slug, is_default, is_active)
select s.id, 'The Proving Drawer', 'proving-drawer', true, true
from seasons s
where s.name = 'GBBO 2026'
  and not exists (select 1 from leagues where slug = 'proving-drawer');

-- ------------------------------------------------------------
-- Ten episodes
-- ------------------------------------------------------------
-- Numbers only. air_date is NULL until the schedule is announced, and the
-- trigger in schema.sql fills deadline_at in from it automatically — set the
-- date in the GM panel and the 18:00 UK deadline follows, British Summer Time
-- included.
--
-- Until a date is set, deadline_at stays NULL, which means v_public_predictions
-- keeps that episode's picks private. Failing closed is the intended behaviour.
--
-- Episode 10 is the final: no Star Baker, no elimination, no penalty, and the
-- 'winner' category instead. RULES §4.

insert into episodes (season_id, number, is_final)
select s.id, n, (n = 10)
from seasons s
cross join generate_series(1, 10) as n
where s.name = 'GBBO 2026'
on conflict (season_id, number) do nothing;

-- ------------------------------------------------------------
-- Season settings
-- ------------------------------------------------------------
-- top_picks_lock_at is 18:00 UK on the Tuesday before episode 2 — i.e. the same
-- moment as episode 2's own deadline. Left NULL until the schedule lands; the
-- GM panel sets it. Top picks stay private, and unchangeable in the UI, until
-- it passes.

insert into season_settings (season_id, top_picks_lock_at)
select s.id, null
from seasons s
where s.name = 'GBBO 2026'
on conflict (season_id) do nothing;

-- ------------------------------------------------------------
-- Check it landed
-- ------------------------------------------------------------

select
  (select count(*) from categories)                 as categories,
  (select count(*) from seasons)                    as seasons,
  (select count(*) from leagues)                    as leagues,
  (select count(*) from episodes)                   as episodes,
  (select count(*) from episodes where is_final)    as finals,
  (select count(*) from bakers)                     as bakers_awaiting_cast,
  (select count(*) from players)                    as players_awaiting_codes;
